package com.example.campusmaintenance.exception;
import com.example.campusmaintenance.dto.ApiResponse; import jakarta.servlet.http.HttpServletRequest; import org.slf4j.*; import org.springframework.http.*; import org.springframework.http.converter.HttpMessageNotReadableException; import org.springframework.validation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler {private static final Logger log=LoggerFactory.getLogger(GlobalExceptionHandler.class); @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ApiResponse<Void>> nf(ResourceNotFoundException e,HttpServletRequest q){log.warn("Resource not found: {}",e.getMessage());return err(HttpStatus.NOT_FOUND,e.getMessage(),q);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiResponse<Map<String,String>>> val(MethodArgumentNotValidException e,HttpServletRequest q){Map<String,String> m=new LinkedHashMap<>();for(FieldError x:e.getBindingResult().getFieldErrors())m.put(x.getField(),x.getDefaultMessage());log.warn("Validation failed: {}",m);return ResponseEntity.badRequest().body(new ApiResponse<>(false,"Validation failed",m,q.getRequestURI(),MDC.get("correlationId")));} @ExceptionHandler(HttpMessageNotReadableException.class) ResponseEntity<ApiResponse<Void>> body(HttpMessageNotReadableException e,HttpServletRequest q){return err(HttpStatus.BAD_REQUEST,"Malformed JSON or invalid enum value supplied",q);} @ExceptionHandler(Exception.class) ResponseEntity<ApiResponse<Void>> other(Exception e,HttpServletRequest q){log.error("Unexpected server error",e);return err(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected server error occurred",q);} private ResponseEntity<ApiResponse<Void>> err(HttpStatus s,String m,HttpServletRequest q){return ResponseEntity.status(s).body(new ApiResponse<>(false,m,null,q.getRequestURI(),MDC.get("correlationId")));}}
